import React from 'react';
import {AbsoluteFill, Composition, continueRender, delayRender, Freeze, useCurrentFrame} from 'remotion';
import {Captions} from './Captions';
import tl from './data/timeline.json';
import {Main} from './Main';
import {CAIRO, CAVEAT, INTER} from './fontsData';

// Fonts are embedded as base64 (src/fontsData.ts, generated by make_assets.py): no network request, so no render tab
// can stall on them. `retries` makes Remotion reload a tab that still gets stuck instead of failing the whole render.
const b64 = (s: string) => {
  const bin = atob(s);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
};
const fontHandle = delayRender('Loading fonts', {timeoutInMilliseconds: 15000, retries: 4});
const faces = [
  ['Inter', INTER, '100 900'],
  ['Caveat', CAVEAT, '400 700'],
  ['Cairo', CAIRO, '200 1000'],
]
  .filter(([, data]) => data)
  .map(([name, data, weight]) => new FontFace(name, b64(data), {weight}));
Promise.all(faces.map((f) => f.load()))
  .then((loaded) => {
    loaded.forEach((f) => (document.fonts as any).add(f));
    continueRender(fontHandle);
  })
  .catch((e) => {
    console.error('font load failed', e);
    continueRender(fontHandle);
  });

/** renders Main frozen at a list of frames, one output image per listed frame (fast QA contact sheets via prev.sh).
 *  Its duration is the full timeline because <Freeze> clamps to the composition length. */
const Preview: React.FC<{frames: number[]; captions?: boolean}> = ({frames, captions}) => {
  const f = useCurrentFrame();
  return (
    <Freeze frame={frames[Math.min(f, frames.length - 1)]}>
      <Main />
      {captions ? <Captions /> : null}
    </Freeze>
  );
};

/** transparent caption layer, rendered separately and composited by scripts/mux.py (captioned + clean versions) */
const CaptionsOnly: React.FC = () => (
  <AbsoluteFill style={{backgroundColor: 'transparent'}}>
    <Captions />
  </AbsoluteFill>
);

const D = {durationInFrames: tl.totalFrames, fps: tl.fps, width: 1920, height: 1080};
export const Root: React.FC = () => (
  <>
    {/* Studio: render these two (picture + final mastered audio) */}
    <Composition id="Talk-final" component={Main} {...D} defaultProps={{captions: true, audio: 'mastered' as const}} />
    <Composition id="Talk-clean" component={Main} {...D} defaultProps={{captions: false, audio: 'mastered' as const}} />
    {/* used by the scripts */}
    <Composition id="Pipeline" component={Main} {...D} defaultProps={{captions: false, audio: 'live' as const}} />
    <Composition id="CaptionsOnly" component={CaptionsOnly} {...D} />
    <Composition id="Preview" component={Preview as any} {...D} defaultProps={{frames: [0]}} />
  </>
);
